  const goTo = useCallback(
    (i: number) => {
      const n = Math.max(0, Math.min(stops.length - 1, i));
      const el = stops[n];
      if (!el) return;
      if (n === stops.length - 1) {
        slide(document.documentElement.scrollHeight);
